from pathlib import Path
P=Path(__file__).resolve().parent
DATE='2026-11-06'
S={}
def source(key,title,url,publisher,scope,evidence='Official page text or search-index extract reviewed'):
    S[key]={'title':title,'url':url,'publisher':publisher,'reviewedOn':DATE,'scope':scope,'evidence':evidence}
