def refs(*keys): return [{k:S[x][k] for k in ('title','url','publisher')} for x in keys]
def item(title,steps,expected,abnormal,lim,keys,purpose='Compare the item with the listing before accepting it.'):
    return dict(title=title,purpose=purpose,steps=steps,expectedObservation=expected,abnormalSigns=abnormal,limitations=lim,sources=refs(*keys))
rows=[]
LIMIT='A brief check cannot rule out hidden repairs, intermittent faults or future failure. Mark unavailable tests as not checked.'
NOTE='Buyer checklist, not a quality guarantee. Agree acceptable wear and included accessories before testing. Ask permission; do not open the device, erase data or perform destructive tests. Reference documents support operation/configuration; condition observations are InspectFirst editorial checks, not manufacturer resale grades.'
def add(cat,brand,code,name,items,tools='A charged test phone, internet, a compatible charger and the seller present.',note=NOTE):
    rows.append(dict(categorySlug=cat,product=dict(brand=brand,modelCode=code,name=name,status='ACTIVE'),guide=dict(expectedVersion=0,title=name+' inspection',tools=tools,reviewedOn=DATE,contentNote=note,items=items)))

# Phones: common lock check is deliberately brief; model references support the other checks.
for code,name,ref,port in [('IPHONE-13','Apple iPhone 13','iphone13','Lightning'),('IPHONE-14','Apple iPhone 14','iphone14','Lightning'),('IPHONE-15','Apple iPhone 15','iphone15','USB-C')]:
    add('phones','Apple',code,name,[
      item('Account and repairs',['Have the seller resolve Activation Lock.','Read About and available service history.'],'Setup is accessible; disclosures match.','Owner lock or unexplained repairs.','History varies by model/software; absence proves nothing.',['iphone-used']),
      item('Screen and Face ID',['Display plain light and dark images; draw across the screen.','With permission, test Face ID enrolment without deleting the seller\'s data.'],'Touch reaches every area; Face ID completes when testable.','Dead areas, persistent marks or Face ID errors.','Protectors and lighting affect results. No universal used-screen pixel allowance.',['%s'%ref]),
      item('Camera, sound and connection',['Take near/far photos with front and rear cameras.','Record and play a short video; test Wi-Fi and an agreed SIM/eSIM if available.'],'Focus and recorded sound work; agreed network works.','Blur, rattling, missing audio or network restriction.','Region/carrier compatibility and water resistance remain unverified. Avoid shaking the phone.',['%s'%ref]),
      item(port+' charging and condition',['Use a known-good '+port+' cable. Inspect the port, edges and back without tools.','Observe charging while taking a short video.'],'Charging stays connected; condition matches disclosed wear.','Swelling, exposed internals, repeated restarts or unreliable charging.','Stop using a swollen/hot device. Short observation does not measure battery endurance.',['%s'%ref])])
for code,name,ref in [('SM-S911B','Samsung Galaxy S23','s23'),('SM-S921B','Samsung Galaxy S24','s24')]:
    add('phones','Samsung',code,name,[
      item('Model and seller access',['Read the model/storage in Settings > About phone; compare the sale.','Seller should remove Google/Samsung accounts and complete agreed setup before handover.'],'Expected model and usable setup.','Different variant, account request or organization restriction.','SM codes vary by region; never bypass locks.',['%s'%ref]),
      item('Interactive diagnostics',['Open Samsung Members diagnostics; run available touch, sound and sensor checks.'],'Available tests finish.','Failed or skipped tests.','Menu and coverage vary.',['members']),
      item('Display and cameras',['Use light/dark images and trace screen edges.','Take front/rear photos and a video; try the camera lenses offered in the app.'],'No persistent defects; normal focus and playback.','Burn-in, dead touch zones, camera errors or distorted audio.','Zoom settings do not all correspond to separate physical lenses.',['%s'%ref]),
      item('Ports, connectivity and battery',['Connect known-good USB-C power and Wi-Fi.','Check frame/back for lifting; observe short ordinary use.'],'Stable connection and no physical separation.','Unexplained shutdown, lifted back or loose port.','No water test. Battery life, carrier compatibility and sealing need separate confirmation.',['%s'%ref])])

# Tablets.
for code,name,ref,port,biometric in [('A2602','Apple iPad 9th generation Wi-Fi','ipad9','Lightning','Home-button Touch ID'),('A2696','Apple iPad 10th generation Wi-Fi','ipad10','USB-C','top-button Touch ID'),('A2588','Apple iPad Air 5th generation Wi-Fi','ipadair5','USB-C','top-button Touch ID')]:
    add('tablets','Apple',code,name,[
      item('Exact generation',['Compare Settings > General > About model number with '+code+'.','Confirm storage, Wi-Fi-only configuration and any included accessories.'],'Agreed configuration matches.','Different model or undisclosed accessories missing.','Tap the model entry if a part number is displayed. Colour/storage cannot be inferred from A-number alone.',['ipad-id']),
      item('Screen and '+biometric,['Draw slowly across the screen and display solid colours.','Ask permission to test '+biometric+' and physical buttons.'],'No dead areas; buttons and permitted biometric test work.','Lines, touch gaps, lifting screen or repeated biometric errors.','A brief test does not establish panel originality. Stylus must be compatible with this exact generation.',['%s'%ref]),
      item('Cameras, speakers and '+port,['Record a short front/rear video and play it.','Connect a known-good '+port+' charger; inspect the casing on a flat surface.'],'Audio/video and charging work; case has no obvious distortion.','Crackling, charge disconnects or bent/lifting enclosure.','Do not bend the tablet. Battery Health information is not available on every iPad.',['%s'%ref]),
      item('Handover readiness',['Ask the seller to remove their account and complete an agreed erase/setup before payment.','If any previous-owner or remote-management prompt appears, pause the handover.'],'Setup is usable without another owner or organization.','Seller cannot release the device.','This is an editorial handover precaution, not proof of ownership or a way to bypass management.',['ipad-id'])])
for code,name,ref in [('SM-X700','Samsung Galaxy Tab S8 Wi-Fi','tabs8'),('SM-X710','Samsung Galaxy Tab S9 Wi-Fi','tabs9')]:
    add('tablets','Samsung',code,name,[
      item('Base model and bundle',['Read About tablet and compare '+code+' with the listing.','Check the agreed S Pen, charger and cover are present.'],'Correct base Wi-Fi tablet and agreed bundle.','S8+/S9+ substituted, mismatched model or missing extras.','Regional package contents vary; a keyboard cover is not automatically included.',['%s'%ref]),
      item('Samsung Members checks',['Run available display, touch and speaker diagnostics in Samsung Members.'],'Tests complete.','Failures or skipped tests.','Not all faults are covered.',['members']),
      item('S Pen and screen',['Using a compatible S Pen, draw a slow grid to the edges.','Check the tip and display against a light/dark image.'],'Continuous lines and responsive touch.','Dead drawing zones, persistent marks or damaged tip.','A magnetic cover can interfere; retest without it. Pen air actions depend on model/settings.',['%s'%ref]),
      item('Charging and clean handover',['Test USB-C charging, Wi-Fi and front/rear video.','Seller removes their accounts; verify agreed setup is free from previous-owner or organization prompts.'],'Stable functions and usable setup.','Loose charge port, failures or locked setup.','No reset without consent; no water test. Brief use cannot verify battery endurance.',['%s'%ref])])

# Headphones.
for code,name,pro in [('AIRPODS-3','Apple AirPods 3rd generation',False),('AIRPODS-PRO-2-USBC','Apple AirPods Pro 2 USB-C',True)]:
    add('audio','Apple',code,name,[
      item('Buds and case variant',['Read model information on the paired iPhone and compare both buds and case with Apple\'s identification page.'],'Correct generation and case.','Mixed generations or wrong case.','Serials can be copied. Pairing animation is not proof of authenticity.',['airpods-id']),
      item('Previous owner association',['Ask the seller to remove the AirPods from their Apple Account / Find My before handover.'],'No previous-owner warning.','Association remains.','Resetting alone may not release ownership.',['airpods-owner']),
      item('Each ear and microphones',['At a comfortable volume, listen to each bud separately.','Make a short call/recording and try stem controls.' + (' Switch noise control modes and compare in steady background noise.' if pro else '')],'Both sides play clearly and respond.','One silent side, crackle or unusable microphone.','Fit, software and background noise affect results. '+('ANC does not remove every sound.' if pro else 'AirPods 3 do not offer active noise cancellation.'),['airpods-id']),
      item('Case and charging',['Inspect contacts without scraping. Put each bud in the case; connect '+('USB-C' if pro else 'a cable appropriate to the case variant')+'.','Watch whether each bud is detected and charging.'],'Each bud/case responds consistently.','Intermittent contact, damage or no charging.','No liquid cleaning during inspection. Brief charging cannot measure endurance or prove originality.',['airpods-id'])],tools='A compatible iPhone, agreed charging cable, quiet audio sample and seller access.')
for code,name,ref in [('WH-1000XM4','Sony WH-1000XM4','xm4'),('WH-1000XM5','Sony WH-1000XM5','xm5'),('QC45','Bose QuietComfort 45','qc45')]:
    sony=ref!='qc45'
    add('audio','Sony' if sony else 'Bose',code,name,[
      item('Frame and pads',['Examine headband, hinges, pads and exposed ports.','Adjust gently within the normal range; do not force or twist joints.'],'No splits or unexpected looseness.','Cracks, separating joints or damaged pad attachment.','Pad wear is negotiable. Visual condition cannot establish battery or internal health.',['%s'%ref]),
      item('Pairing and stereo audio',['Pair with your phone; play a familiar track at safe volume.','Check left/right balance, microphone and '+('touch controls' if sony else 'physical playback buttons')+'.'],'Stable stereo sound and working controls.','Dropouts, crackle or unresponsive controls.','Retest with another track/device; wireless interference can mimic faults.',['%s'%ref]),
      item('Noise control modes',['Compare '+('ANC and ambient sound' if sony else 'Quiet and Aware')+' with steady background noise.','Fit the pads normally; keep microphones uncovered.'],'Modes change the listening experience.','No repeatable difference after fit/settings are checked.','Not silence or a lab attenuation measurement.',['xm5-anc' if ref=='xm5' else ref]),
      item('USB-C and included cable',['Use known-good USB-C charging; inspect the indicator.','If an audio cable is included, test wired playback and the plug.'],'Charging and agreed wired playback work.','Loose connection, no indicator or intermittent audio.','A short charge does not establish battery capacity; wired mode may behave differently from Bluetooth.',['%s'%ref])],tools='A test phone, known-good USB-C power, audio track and any included audio cable.')

# Computers.
for code,name,ref,ports in [('MACBOOK-AIR-M1-2020','Apple MacBook Air M1 2020','m1','both USB-C ports'),('MACBOOK-AIR-M2-2022','Apple MacBook Air M2 2022','m2','MagSafe and both USB-C ports'),('MACBOOK-PRO-14-2021','Apple MacBook Pro 14-inch 2021','macpro14','the included charger and accessible ports')]:
    add('computers','Apple',code,name,[
      item('Configuration and physical condition',['Compare About This Mac, memory and storage with the listing.','Inspect display, hinges, keyboard and case without opening it.'],'Agreed configuration and wear.','Wrong year/chip, swelling or damaged hinges.','Configuration varies; case labels alone do not prove the installed hardware.',['%s'%ref]),
      item('Apple Diagnostics',['With permission, shut down; hold power for startup options, then press Command-D.','Follow Apple\'s current instructions; record any code.'],'Test completes.','Reported hardware error.','A pass is not a guarantee.',['mac-diagnostics']),
      item('Display, input and power',['Type across the keyboard; test trackpad, webcam, sound and Wi-Fi.','Try '+ports+' with known-good compatible equipment.'],'All agreed functions work.','Dead keys/pixels, flicker, disconnects or unexpected shutdown.','Unavailable adapters mean untested ports. Do not install firmware or stress-test during handover.',['%s'%ref]),
      item('Ownership and setup',['Seller removes Find My / Activation Lock and completes agreed handover.','Pause if setup asks for another owner or organization.'],'Setup available.','Unreleased lock/management.','Never bypass access controls.',['mac-lock'])],tools='Compatible charger, Wi-Fi, optional USB-C device and seller permission.')
add('computers','Dell','LATITUDE-5420','Dell Latitude 5420',[
 item('Exact laptop and configuration',['Read model and Service Tag in BIOS/system information; compare seller details.','Confirm it is Latitude 5420, not E5420 or 5420 Rugged.'],'Agreed model and configuration.','Different family, undisclosed damage or mismatch.','Service Tag identifies support configuration, not legal ownership.',['dell']),
 item('F12 diagnostics',['With permission, enter F12 boot options and select Diagnostics.','Record errors; if BIOS administrator credentials are requested, ask the seller to resolve them.'],'Diagnostics can complete.','Hardware errors or seller cannot unlock test access.','A password block is not itself a hardware failure. Do not bypass it.',['dell']),
 item('Practical workstation test',['Type all keys; test touchpad, webcam, speakers and Wi-Fi.','Test agreed ports with known-good compatible devices; keep a record of skipped ports.'],'Agreed functions work.','Dead keys, flicker, disconnects or missing sound.','Editorial checklist, not a Dell resale grade. A short test misses intermittent faults.',['dell']),
 item('Power and ownership handover',['Check charger recognition and visible case condition.','Observe ordinary use on battery, then reconnect power. Verify agreed setup has no previous-owner/organization restriction.'],'Stable power and usable setup.','Swelling, restarts, charging errors or locked setup.','Do not open the case. Battery endurance and corporate release require separate confirmation.',['dell'])],tools='Compatible charger, Wi-Fi, USB device and seller access.')
add('computers','Lenovo','T14-GEN2-INTEL','Lenovo ThinkPad T14 Gen 2 Intel',[
 item('Intel generation and configuration',['Compare model/CPU/memory/storage in system information with the listing and Intel PSREF.','Confirm touch/non-touch screen and keyboard options actually supplied.'],'Expected Intel generation/configuration.','AMD/different generation substituted or options missing.','PSREF lists possible options, not what every unit includes.',['thinkpad']),
 item('Keyboard, TrackPoint and screen',['Type across the keyboard, use TrackPoint/touchpad and test display with plain images.','Only test touch if this unit has a touch panel.'],'Inputs and selected screen functions work.','Dead keys, drifting input or persistent display faults.','No touch response on a non-touch configuration is not a defect.',['thinkpad']),
 item('Connections and conferencing',['Test Wi-Fi, webcam/shutter, microphone and speakers.','Connect known-good compatible USB-C power and agreed peripherals.'],'Working functions and stable power.','Dropouts, loose sockets or unusable camera/audio.','An untested optional port stays untested; no high-load endurance claim.',['thinkpad']),
 item('Case, battery and handover',['Inspect hinges and underside for cracks or lifting.','Ask seller to resolve firmware passwords and organization/owner setup restrictions before payment.'],'Condition matches; setup is usable.','Swelling, broken hinge or unresolved lock.','Editorial handover checks; documentation does not certify used condition or ownership.',['thinkpad'])],tools='Compatible USB-C charger, Wi-Fi, USB device and seller access.')

# Furniture: no unsafe load/tip tests. Reference matching is separate from editorial wear checks.
furn=[('00522047','IKEA BILLY bookcase white 80 x 28 x 202 cm','billy','shelf supports, shelves and back-panel fittings','Inspect shelf edges and back-panel attachment; look for bowed shelves or swollen lower panels.','Do not stand the bookcase unsecured; wall-fixing hardware must suit the wall.'),('70351886','IKEA KALLAX shelving white 77 x 77 cm','kallax','dividers, side panels and agreed inserts','Inspect divider joints, exposed corners and the underside for crushed or water-swollen panels.','Check the exact assembly guide for required wall fixation; inserts are not automatically included.'),('POANG-BIRCH-FRAME','IKEA POANG birch-veneer armchair frame','poang','frame sections, fasteners and agreed cushion','Inspect curved frame laminations and seat support for splits, separation or damaged attachment points.','Do not sit on an incomplete/loose frame or force the curved wood. Match the correct manual revision.'),('80354276','IKEA MICKE desk white 105 x 50 cm','micke','drawer, door, runners and fasteners','With the empty desk supported on level ground, gently open and close the door/drawer; inspect runner attachment.','Stop if the desk is unstable. Do not pull furniture over by the drawer.'),('10449909','IKEA LACK side table white 55 x 55 cm','lack','four legs and their fastening points','Inspect leg-to-top joints, corners and underside for torn fastenings, dents or water swelling.','Do not stand, sit or perform a weight test on the table.')]
for code,name,ref,parts,wear,safe in furn:
 add('furniture','IKEA',code,name,[
  item('Model and dimensions',['Read the label if present; compare dimensions/finish with the listing.','Use the matching product/assembly document rather than a similar-looking version.'],'Agreed size and configuration.','Wrong size or changed construction.','Regional articles and older editions can differ.',['%s'%ref]),
  item('Completeness',['Count '+parts+' against the correct assembly instructions.','Photograph missing/damaged parts; confirm what the seller includes.'],'Required parts present.','Missing fasteners/supports or substituted parts.','Do not improvise structural repairs. Accessories are included only if agreed.',['%s'%ref]),
  item('Wear and damage',[wear,'Inspect under good light without disassembly.'],'No obvious structural damage; wear matches agreement.','Splits, swelling, broken joints or movement at a damaged connection.','Visual check cannot rule out concealed weakness. No heavy load test.',['%s'%ref]),
  item('Safe collection and installation',[safe,'Plan safe transport and reassembly; resolve any missing structural parts before use.'],'Safe installation is achievable.','Cannot assemble safely or no suitable fixing plan where required.','A collection inspection does not certify structural safety. Do not climb, tip-test or deliberately overload furniture.',['%s'%ref])],tools='Tape measure, flashlight, camera and the correct assembly instructions.',note='Editorial second-hand condition checks with manufacturer configuration/assembly references. Not an engineering safety certification. Stop when unstable; never stress-load, climb or deliberately tip furniture. Match the exact article and manual revision. Check current local recalls separately before purchase.')

# Luxury: consistency/risk screening only. Never label a bag genuine from a serial/logo.
lux=[('Louis Vuitton','M41178','Louis Vuitton Neverfull MM Monogram','lv-neverfull','Monogram canvas, handles, side ties and the agreed removable pouch','handle bases, top edge, side ties and interior','lv-dates'),('Louis Vuitton','M46977','Louis Vuitton Speedy Bandouliere 25 Monogram','lv-speedy','Monogram body, zip opening, handles and agreed shoulder strap','handle tabs, strap attachment points, zip ends and base corners','lv-dates'),('CHANEL','A01112-Y01295-94305','CHANEL Classic 11.12 black lambskin','chanel','black lambskin, flap construction, chain and gold-tone hardware','flap edges, quilting, chain contact areas and lining','chanel-auth'),('Gucci','447632-DTD1T-1000','Gucci GG Marmont small black camera bag','gucci','black camera-bag shape, zip opening, Double G hardware and chain/leather strap','zip corners, strap attachments, quilting and interior','gucci-auth'),('Prada','1BH204-R064-F0002','Prada Re-Edition 2005 Re-Nylon black','prada','Re-Nylon body with Saffiano trim and the agreed strap, chain and detachable accessories','nylon seams, zip track, trim and strap attachments','prada-auth')]
